var l=[{title:`Чому скринінг важливий`,text:`Більшості людей корисно рухатися більше, і м’який рух часто є добрим початком. Симптоми, нестабільні стани здоров’я чи нещодавні медичні події можуть змінити, які види активності для вас безпечні. Скринінг показує, коли медичний працівник або кваліфікований фахівець із фізичних вправ має скерувати ваші наступні кроки.`},{title:`PAR-Q+`,text:`Чинний Опитувальник готовності до фізичної активності для всіх (PAR-Q+) використовує структуровані запитання про здоров’я з подальшими шляхами, тож виходить за межі одного загального чек-листа. Подумайте про захворювання серця чи судин, неконтрольований артеріальний тиск, непритомність або незрозуміле запаморочення, дискомфорт у грудях, нещодавню операцію, новий або посилений біль і ліки, що змінюють реакцію тіла на вправи. Вагітність і місяці після пологів також потребують індивідуальної поради.`},{title:`Що означає відповідь «так»`,text:`Відповідь «так» на запитання скринінгу автоматично не означає відмову від вправ. Вона може означати, що потрібно завершити офіційний наступний процес або отримати пораду щодо інтенсивності та обмежень. Якщо ви вже безпечно тренуєтеся, продовження на звичному рівні є іншим рішенням, ніж початок важких тренувань, яких ви ніколи не робили.`},{title:`Приклад`,text:`Людині, яка роками була неактивною і відчуває тиск у грудях під час швидкої ходьби, не слід пробувати максимальне силове чи інтервальне заняття. Їй слід припинити цю активність і пройти медичну оцінку. Сильні або тривалі симптоми в грудях потребують невідкладної допомоги. Людина без тривожних симптомів може почати з легкої ходьби та легкої силової практики, а потім поступово нарощувати навантаження.`},{title:`Як це працює в TrainUp`,text:`У Профілі ви можете вказати обмеження за ділянками тіла з нотатками, і план добирає лише вправи, що їм відповідають. TrainUp не може підтвердити відсутність медичного стану чи інтерпретувати ваші симптоми, а згенероване тренування не є медичним дозволом. Якщо скринінг викликає занепокоєння, запитайте лікаря, перш ніж обирати вимогливий план.`}];var i=[{label:`Офіційний скринінг PAR-Q+`,url:`https://eparmedx.com/`},{label:`CDC: з чого почати`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`}];var a={sections:l,sources:i};export{a as default,l as sections,i as sources};